    "请按以下步骤导入订阅：\\n1. 打开Clash Verge软件\\n2. 点击左侧\"配置\"选项卡\\n3. 点击\"新建\"按钮\\n4. 选择\"从链接导入\"\\n5. 将订阅链接粘贴到输入框中\\n6. 点击\"导入\"按钮": "按照以下步驟將鏈接輸入 Clash Verge：\n1. 打開 Clash Verge\n2. 選擇“配置”標籤\n3. 點擊“創建新建”\n4. 選擇“從鏈接導入”\n5. 粘貼註冊鏈接\n6. 點擊“導入”",
    "请按以下步骤导入订阅：\\n1. 打开SingBox软件\\n2. 点击\"配置\"选项卡\\n3. 点击\"添加配置\"按钮\\n4. 选择\"从URL导入\"\\n5. 将订阅链接粘贴到输入框中\\n6. 点击\"导入\"按钮": "按照以下步驟將連結輸入 SingBox：\n1. 打開 SingBox\n2. 選擇「配置」標籤\n3. 點擊「新增配置」\n4. 選擇「從 URL 導入」\n5. 貼上訂閱連結\n6. 點擊「導入」",
    "请按以下步骤导入订阅：\\n1. 打开V2rayN软件\\n2. 右键点击系统托盘中的V2rayN图标\\n3. 选择\"订阅分组\" → \"订阅设置\"\\n4. 点击\"添加\"按钮\\n5. 将订阅链接粘贴到\"地址(url)\"框中\\n6. 点击\"确定\"保存\\n7. 右键托盘图标选择\"更新订阅\"": "按照以下步驟將連結輸入到 V2rayN：\n1. 打開 V2rayN\n2. 在系統托盤圖標上點擊右鍵\n3. 選擇 訂閱群組 → 訂閱設置\n4. 點擊 新增\n5. 在 URL 地址欄中粘貼連結\n6. 點擊 確認 以保存\n7. 選擇 更新訂閱",
